{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "We attempt to understand how touch communication seems to be structured in the literature, and what tends to be communicated via touch, but also to highlight how the dogmatic distinction between 'instrumental' and 'expressive' touches might have obscured a socio-affective matrix within all touches.",
      "reason": "The abstract describes the current state of knowledge (the distinction between instrumental and expressive touch) and the uncertainty/gap (the socio-affective matrix that is obscured by this distinction)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In light of this brief background analysis, the present review sets itself apart from previous ones by attempting to understand the communicative, social and affective dimensions of touch in healthcare and nursing professions, in both its instrumental and expressive instances. Our approach provides a comprehensive overview of the phenomenon without privileging one type of touch over another and teases out conceptual and methodological issues that might have been partly obscured in the studies examined and overlooked in previous reviews.",
      "reason": "The text explains the importance and need for the review by highlighting that it addresses issues overlooked in previous reviews and provides a more comprehensive overview."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In light of this brief background analysis, the present review sets itself apart from previous ones by attempting to understand the communicative, social and affective dimensions of touch in healthcare and nursing professions, in both its instrumental and expressive instances. Our approach provides a comprehensive overview of the phenomenon without privileging one type of touch over another and teases out conceptual and methodological issues that might have been partly obscured in the studies examined and overlooked in previous reviews.",
      "reason": "The authors explicitly acknowledge previous reviews and explain the need for the current review by stating it addresses issues overlooked in those previous works."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a qualitative systematic review exploring concepts and themes, not a review of intervention effects (e.g., clinical efficacy of a specific treatment), so a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not evaluating a complex intervention or delivery context requiring a logic model; it is a thematic synthesis of qualitative and mixed-methods studies on the concept of touch."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "A PICo (Population, Interest, Context) framework ([45]; see also: [46]) was used to formulate the preliminary question 'What are care-givers' (i.e. allied health professionals, nurses, doctors, carers) [Population] actual uses and experiences of touch [Interest] when providing real and direct medical care to patients [Context]?'",
      "reason": "The review explicitly states its research question and identifies the PICo framework used to formulate it."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of intervention effects (it is an exploratory systematic review of qualitative and quantitative studies on touch in healthcare), so the requirement to state planned comparisons using PICO for intervention effects does not apply."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "A PICo (Population, Interest, Context) framework ([45]; see also: [46]) was used to formulate the preliminary question 'What are care-givers' (i.e. allied health professionals, nurses, doctors, carers) [Population] actual uses and experiences of touch [Interest] when providing real and direct medical care to patients [Context]?' . From this question, PICo was also used to devise inclusion and exclusion criteria... Both qualitative and quantitative studies were considered eligible, but non-empirical studies were not ('non-empirical' exclusion criterion). No specific sociometric variables (e.g. sex, age, socioeconomic status of participants) were sought, and studies were not excluded on the basis of their design (e.g. number of participants, methods).",
      "reason": "The review explicitly defines eligibility using the PICo framework (Population, Interest, Context) and specifies eligible study designs (qualitative and quantitative) and exclusions (non-empirical studies)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The present review is exploratory in nature: for this reason, studies from all years and in any language spoken by the team (i.e. English, Italian, French, Spanish, Finnish) were included ('Language' exclusion criterion).",
      "reason": "The review specifies criteria for dissemination year (all years) and language (English, Italian, French, Spanish, Finnish)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "For instance, studies such as those of [54, 55] and [56] initially appeared to respond to the question posed by the present review; upon a closer appraisal however, they were all excluded because they focused solely on assessing the functional dynamics and efficacy of touch interventions, without exploring the impact of such a touch experience on either the practitioner or the patient. Moreover, studies such as [57] were excluded because they solely focused on what touch does, without enquiring into what these haptic engagements are, as well as when how they happen in the specific medical context analysed",
      "reason": "The text distinguishes between studies excluded for scope/content (e.g., focusing on functional dynamics/efficacy without exploring impact) versus those that might have been excluded for other reasons, clearly articulating the rationale for exclusion based on the depth of the research question rather than just the absence of a reported outcome."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "In conformity with guidelines on thematic synthesis [64], through a third read, descriptive themes were connected into 4 higher-level analytical themes. A final readthrough and categorisation carried out by the whole team then aimed to explore some of the issues presented in the discussion, as well as to perform a confidence assessment of the themes via the CERQual tool [65], and a heterogeneity analysis of the reported results (Appendix 5).",
      "reason": "The review specifies the grouping of studies through thematic synthesis, where studies were allocated to descriptive themes and then higher-level analytical themes, which are linked to the review's objectives of uncovering theoretical assumptions."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Two of them ('language' and 'non-empirical') were based on the team expertise and the general aim of this review (i.e. capturing empirical social analysis over anecdotal case studies or philosophical discussions), while the other 8 were formulated starting from the PICo framework.",
      "reason": "The review provides a rationale for the exclusion criteria, specifically noting that 'language' and 'non-empirical' criteria were based on team expertise and the aim to capture empirical social analysis."
    }
  ],
  "confidence": 100
}

